using System.Text;
using System.Xml.Linq;
using EqlTracker.Core;

internal static class AdditionalTests
{
    private static void Check(bool value, string message = "Assertion failed") { if (!value) throw new Exception(message); }
    private static void Equal<T>(T expected, T actual) { if (!EqualityComparer<T>.Default.Equals(expected, actual)) throw new Exception($"Expected {expected}, got {actual}"); }
    private static void Refused(Action action)
    { try { action(); } catch (Exception e) when (e is InvalidOperationException or InvalidDataException) { return; } throw new Exception("Operation should have been refused"); }
    private static readonly DateTime Start = new(2026, 10, 14, 21, 0, 0);
    private static Encounter Fight(DateTime? start = null)
    {
        var t = start ?? Start;
        var f = new Encounter { Start = t, End = t.AddSeconds(20), Finished = true, Events =
        [
            new() { Time = t, Owner = "Player", Kind = "Melee", Ability = "slashes", Damage = 1000, Target = "giant" },
            new() { Time = t.AddSeconds(5), Owner = "Pet", Kind = "Melee", Ability = "pierces", Damage = 200, Target = "giant" },
            new() { Time = t.AddSeconds(7), Owner = "Unknown", Kind = "Spell", Ability = "unattributed", Damage = 77, Target = "giant" },
            new() { Time = t.AddSeconds(15), Owner = "Pet", Kind = "Spell", Ability = "Frost Strike", Damage = 100, Target = "giant", Critical = true },
            new() { Time = t.AddSeconds(20), Owner = "Player", Kind = "Spell", Ability = "Spirit Tap", Damage = 500, Target = "giant" }
        ] }; CombatEngine.Recount(f); return f;
    }
    private static (string Root, string Package, string Character, string Ui) Fixture(bool occupied = false, bool allBars = false)
    {
        string root = Path.Combine(Path.GetTempPath(), "EQLTracker-native-tests-" + Guid.NewGuid().ToString("N")); Directory.CreateDirectory(root);
        string profile = Path.Combine(root, "ExampleHero_example_LO1.ini"), ui = Path.Combine(root, "UI_ExampleHero_example_LO1.ini");
        var ini = new StringBuilder("; keep this comment\r\n[Defaults]\r\nMusic=6\r\n[Socials]\r\nPage2Button1Name=Auto Buff\r\nPage2Button1Line1=/memspellset buff\r\n[HotButtons]\r\nPage1Button1=H0,@-1,0000,0,,\r\n");
        if (allBars) for (int i = 2; i <= 11; i++) ini.Append($"[HotButtons{i}]\r\nPage1Button1=J27,@-1,0000,0,Forage,\r\n");
        else if (occupied) ini.Append("[HotButtons11]\r\nPage7Button9=J27,@-1,0000,0,Forage,\r\n");
        File.WriteAllText(profile, ini.ToString(), new UTF8Encoding(true));
        File.WriteAllText(ui, "[Main]\r\nUISkin=Rune4K_Frost_Clear\r\n[HotButtonWnd11]\r\nShow=0\r\nWidth=99\r\nHeight=272\r\n[PlayerWindow]\r\nShow=1\r\n", new UTF8Encoding(false));
        string skin = Path.Combine(root, "uifiles", "Rune4K_Frost_Clear"); Directory.CreateDirectory(skin);
        var xml = new XElement("XML", new XAttribute("ID", "EQInterfaceDefinitionLanguage"));
        for (int i = 1; i <= 12; i++) xml.Add(new XElement("HotButton", new XAttribute("item", "HB_Button" + i), new XElement("ScreenID", "HB_Button" + i), new XElement("Size", new XElement("CX", 40), new XElement("CY", 40)), new XElement("Template", "BDT_Square")));
        xml.Add(new XElement("TileLayoutBox", new XAttribute("item", "HB_HotButtonLayout"), new XElement("ScreenID", "HB_HotButtonLayout"), Enumerable.Range(1, 12).Select(i => new XElement("Pieces", "HotButton:HB_Button" + i))));
        xml.Add(new XElement("Screen", new XAttribute("item", "HotButtonWnd11"), new XElement("Pieces", "TileLayoutBox:HB_HotButtonLayout")));
        File.WriteAllText(Path.Combine(skin, "EQUI_HotButtonWnd.xml"), xml.ToString());
        return (root, Path.Combine(root, "setup-package"), profile, ui);
    }
    public static void Register(Action<string, Action> test)
    {
        (string Root, string Package, string Character, string Ui, string Repair) LegacyLabels()
        {
            var f = Fixture(); var plan = NativeSetup.Generate(f.Root, "ExampleHero", "example", f.Package); NativeSetup.Apply(f.Package, true, () => false);
            string text = File.ReadAllText(f.Character);
            foreach (var (label, slot) in plan.Macros) { string prefix = $"Page{slot / 12 + 1}Button{slot % 12 + 1}"; string shortName = label switch { "Classes" => "Who", "Inventory" => "Inv", _ => label }; text = text.Replace(prefix + "Name=" + shortName, prefix + "Name=EQL" + (label == "Inventory" ? "Inv" : label)); }
            File.WriteAllText(f.Character, text, new UTF8Encoding(true));
            return (f.Root, f.Package, f.Character, f.Ui, f.Package + "-labels");
        }
        test("Native labels fit the original buttons without EQL prefixes", () => { var f = Fixture(); NativeSetup.Generate(f.Root, "ExampleHero", "example", f.Package); NativeSetup.Apply(f.Package, true, () => false); string text = File.ReadAllText(f.Character); foreach (string name in new[] { "Log", "Who", "Inv", "Sync" }) Check(text.Contains("Name=" + name + "\r\n")); Check(!text.Contains("Name=EQL")); });
        test("Label-only repair preserves commands bindings skin and placement", () => { var f = LegacyLabels(); string before = File.ReadAllText(f.Character); byte[] ui = File.ReadAllBytes(f.Ui), xml = File.ReadAllBytes(Path.Combine(f.Root, "uifiles", "Rune4K_Frost_Clear", "EQUI_HotButtonWnd.xml")); var plan = NativeSetup.GenerateLabelRepair(f.Package, f.Repair); Check(plan.LabelRepairOnly); Equal(1, plan.Files.Count); Equal(4, plan.Files.Single().Changes.Count); NativeSetup.Apply(f.Repair, true, () => false); string expected = before.Replace("Name=EQLLog", "Name=Log").Replace("Name=EQLClasses", "Name=Who").Replace("Name=EQLInv", "Name=Inv").Replace("Name=EQLSync", "Name=Sync"); Equal(expected, File.ReadAllText(f.Character)); Check(ui.SequenceEqual(File.ReadAllBytes(f.Ui))); Check(xml.SequenceEqual(File.ReadAllBytes(Path.Combine(f.Root, "uifiles", "Rune4K_Frost_Clear", "EQUI_HotButtonWnd.xml")))); NativeSetup.Apply(f.Repair, true, () => false); Equal(expected, File.ReadAllText(f.Character)); NativeSetup.Restore(f.Repair, () => false); Equal(before, File.ReadAllText(f.Character)); });
        test("Label repair refuses writes while the client runs", () => { var f = LegacyLabels(); NativeSetup.GenerateLabelRepair(f.Package, f.Repair); byte[] before = File.ReadAllBytes(f.Character); Refused(() => NativeSetup.Apply(f.Repair, true, () => true)); Check(before.SequenceEqual(File.ReadAllBytes(f.Character))); Check(!Directory.Exists(Path.Combine(f.Repair, "applied-backups"))); });
        test("Label repair refuses changed macro commands", () => { var f = LegacyLabels(); File.WriteAllText(f.Character, File.ReadAllText(f.Character).Replace("Line1=/who", "Line1=/dance")); Refused(() => NativeSetup.GenerateLabelRepair(f.Package, f.Repair)); Check(!Directory.Exists(f.Repair)); });
        test("Label repair rechecks commands after package review", () => { var f = LegacyLabels(); NativeSetup.GenerateLabelRepair(f.Package, f.Repair); File.WriteAllText(f.Character, File.ReadAllText(f.Character).Replace("Line1=/who", "Line1=/dance")); byte[] before = File.ReadAllBytes(f.Character); Refused(() => NativeSetup.Apply(f.Repair, true, () => false)); Check(before.SequenceEqual(File.ReadAllBytes(f.Character))); });
        test("Meter selects newest encounter regardless of storage order", () => { var older = Fight(Start.AddDays(-1)); var newer = Fight(); var view = DpsViews.Build([newer, older], null, Start, new()); Equal(newer.Id, view.Fights.Single().Id); });
        test("Meter prefers the active encounter", () => { var active = Fight(); active.Finished = false; var view = DpsViews.Build([Fight(Start.AddDays(1))], active, Start, new()); Equal(active.Id, view.Fights.Single().Id); Check(view.InCombat); });
        test("Actor meter totals reconcile with breakdowns", () => { var f = Fight(); foreach (var (actor, total) in new[] { ("Pet", 300L), ("Player", 1500L), ("Combined", 1800L) }) { var view = DpsViews.Build([f], null, Start, new() { Actor = actor }); Equal(total, view.Damage); Equal(total, view.Rows.Sum(x => x.Damage)); Equal(total / 20d, view.Dps); Equal(100d, Math.Round(view.Rows.Sum(x => x.Percent), 5)); Equal(77L, view.UnknownDamage); } });
        test("Session boundary clips an encounter crossing launch", () => { var view = DpsViews.Build([Fight()], null, Start.AddSeconds(10), new() { Scope = "Session", Actor = "Combined" }); Equal(600L, view.Damage); Equal(10d, view.Seconds); Equal(60d, view.Dps); });
        test("Session excludes prior encounters and shares duration across actors", () => { var view = DpsViews.Build([Fight(), Fight(Start.AddDays(-1))], null, Start, new() { Scope = "Session" }); Equal(1, view.Fights.Count); Equal(15d, view.PetDps); Equal(75d, view.PlayerDps); Equal(90d, view.CombinedDps); });
        test("Meter ability filter retains encounter denominator", () => { var view = DpsViews.Build([Fight()], null, Start, new() { Ability = "Frost", Actor = "Pet" }); Equal(20d, view.Seconds); Equal(5d, view.Dps); Equal(100L, view.SpellDamage); Equal(0L, view.MeleeDamage); });
        test("Meter critical target and kind filters reconcile", () => { var view = DpsViews.Build([Fight()], null, Start, new() { CriticalOnly = true, Kind = "Spell", Target = "giant", Actor = "Pet" }); Equal(100L, view.Damage); Equal(100d, view.Rows.Single().CriticalPercent); });
        test("Meter date range clips all actor totals identically", () => { var view = DpsViews.Build([Fight()], null, Start, new() { From = Start.AddSeconds(10), Until = Start.AddSeconds(20), Actor = "Combined" }); Equal(60d, view.CombinedDps); Equal(10d, view.PetDps); Equal(50d, view.PlayerDps); });
        test("Meter sorting supports average and strike count", () => { var a = new DamageRow("A", "Melee", 200, 10, 10, 20, 20, 0, 0, 0, 50); var b = a with { Ability = "B", Hits = 1, Average = 200 }; Equal("B", DpsViews.Sort([a, b], "Average")[0].Ability); Equal("A", DpsViews.Sort([a, b], "Hits")[0].Ability); Equal("A", DpsViews.Sort([b, a], "Damage")[0].Ability); });
        test("Equal strike totals sort deterministically across damage channels", () => { var cold = new DamageRow("Strike", "Spell", 200, 10, 10, 20, 20, 0, 0, 0, 50, "Cold"); var fire = cold with { Channel = "Fire" }; Check(DpsViews.Sort([fire, cold], "Damage").Select(x => x.Channel).SequenceEqual(DpsViews.Sort([cold, fire], "Damage").Select(x => x.Channel))); });
        test("Summary-only meter preserves totals without inventing rows", () => { var f = Fight(); f.DetailAvailable = false; f.Events.Clear(); var view = DpsViews.Build([f], null, Start, new()); Equal(300L, view.Damage); Equal(0, view.Rows.Count); Check(!view.DetailComplete); Equal(0L, DpsViews.Build([f], null, Start, new() { Ability = "Frost" }).Damage); });
        test("Saved meter selection and roster timestamp survive restart", () => { string folder = Path.Combine(Path.GetTempPath(), "EQLTracker-meter-" + Guid.NewGuid().ToString("N")); var p = new CharacterProfile { Meter = new() { Actor = "Combined", Scope = "Session", Sort = "Hits", Ability = "Frost" }, ClassesObservedAt = Start }; using (var store = new TrackerStore(Path.Combine(folder, "tracker.db"))) store.Set("profile", p); using (var store = new TrackerStore(Path.Combine(folder, "tracker.db"))) { var saved = store.Get<CharacterProfile>("profile")!; Equal("Combined", saved.Meter.Actor); Equal("Hits", saved.Meter.Sort); Equal(Start, saved.ClassesObservedAt!.Value); } });
        test("Native package prefers bar 11 and retains macros and BOM", () => { var f = Fixture(); var plan = NativeSetup.Generate(f.Root, "ExampleHero", "example", f.Package); Equal(11, plan.Bar); Equal(4, plan.Macros.Count); Check(plan.CompactAvailable); NativeSetup.Apply(f.Package, true, () => false); string text = File.ReadAllText(f.Character); Check(text.Contains("Page2Button1Name=Auto Buff\r\n")); Check(text.Contains("Page1Button1=H0,@-1,0000,0,,\r\n")); Check(text.Contains("/pause 2, /who")); Check(File.ReadAllBytes(f.Character).AsSpan().StartsWith(new byte[] { 0xEF, 0xBB, 0xBF })); });
        test("Compact skin retains all native button ScreenIDs", () => { var f = Fixture(); NativeSetup.Generate(f.Root, "ExampleHero", "example", f.Package); NativeSetup.Apply(f.Package, true, () => false); var xml = XDocument.Load(Path.Combine(f.Root, "uifiles", "Rune4K_Frost_Clear", "EQUI_HotButtonWnd.xml")); for (int i = 1; i <= 12; i++) Equal("HB_Button" + i, xml.Root!.Elements("HotButton").Single(x => (string?)x.Attribute("item") == "EQLTracker_Button" + i).Element("ScreenID")!.Value); });
        test("Occupied bar 11 falls back without touching existing assignments", () => { var f = Fixture(occupied: true); var plan = NativeSetup.Generate(f.Root, "ExampleHero", "example", f.Package); Equal(10, plan.Bar); Check(!plan.CompactAvailable); NativeSetup.Apply(f.Package, false, () => false); Check(File.ReadAllText(f.Character).Contains("Page7Button9=J27,@-1,0000,0,Forage,")); });
        test("All occupied native bars refuse setup", () => { var f = Fixture(allBars: true); Refused(() => NativeSetup.Generate(f.Root, "ExampleHero", "example", f.Package)); Check(!Directory.Exists(f.Package)); });
        test("Native setup refuses while game is running before any write", () => { var f = Fixture(); NativeSetup.Generate(f.Root, "ExampleHero", "example", f.Package); var before = File.ReadAllBytes(f.Character); Refused(() => NativeSetup.Apply(f.Package, true, () => true)); Refused(() => NativeSetup.Restore(f.Package, () => true)); Check(before.SequenceEqual(File.ReadAllBytes(f.Character))); Check(!Directory.Exists(Path.Combine(f.Package, "applied-backups"))); });
        test("Native install is idempotent and Standard removes compact XML", () => { var f = Fixture(); NativeSetup.Generate(f.Root, "ExampleHero", "example", f.Package); NativeSetup.Apply(f.Package, true, () => false); var before = File.ReadAllBytes(f.Character); NativeSetup.Apply(f.Package, true, () => false); Check(before.SequenceEqual(File.ReadAllBytes(f.Character)), "Repeat install changed character bytes: " + f.Root); NativeSetup.Apply(f.Package, false, () => false); Check(!File.ReadAllText(Path.Combine(f.Root, "uifiles", "Rune4K_Frost_Clear", "EQUI_HotButtonWnd.xml")).Contains("EQLTracker_"), "Standard mode retained compact XML"); Check(File.ReadAllText(f.Ui).Contains("Width=525"), "Standard bar width was not applied"); });
        test("Native installer retains unrelated edits made after package review", () => { var f = Fixture(); NativeSetup.Generate(f.Root, "ExampleHero", "example", f.Package); File.WriteAllText(f.Character, File.ReadAllText(f.Character).Replace("Music=6", "Music=9"), new UTF8Encoding(true)); NativeSetup.Apply(f.Package, true, () => false); Check(File.ReadAllText(f.Character).Contains("Music=9")); NativeSetup.Restore(f.Package, () => false); Check(File.ReadAllText(f.Character).Contains("Music=9")); Check(!File.ReadAllText(f.Character).Contains("/outputfile inventory")); });
        test("Native restoration preserves subsequent user edits", () => { var f = Fixture(); NativeSetup.Generate(f.Root, "ExampleHero", "example", f.Package); NativeSetup.Apply(f.Package, true, () => false); File.WriteAllText(f.Ui, File.ReadAllText(f.Ui).Replace("XPos=0.625000%", "XPos=20.000000%")); NativeSetup.Restore(f.Package, () => false); string text = File.ReadAllText(f.Ui); Check(text.Contains("XPos=20.000000%")); Check(text.Contains("Show=0")); });
        test("Macro collision refuses the entire native install", () => { var f = Fixture(); var plan = NativeSetup.Generate(f.Root, "ExampleHero", "example", f.Package); int slot = plan.Macros["Log"]; string text = File.ReadAllText(f.Character).Replace("[Socials]", $"[Socials]\r\nPage{slot / 12 + 1}Button{slot % 12 + 1}Name=My new macro"); File.WriteAllText(f.Character, text, new UTF8Encoding(true)); var before = File.ReadAllBytes(f.Ui); Refused(() => NativeSetup.Apply(f.Package, true, () => false)); Check(before.SequenceEqual(File.ReadAllBytes(f.Ui))); });
        test("New occupancy on another page refuses native install", () => { var f = Fixture(); NativeSetup.Generate(f.Root, "ExampleHero", "example", f.Package); File.AppendAllText(f.Character, "[HotButtons11]\r\nPage2Button5=J27,@-1,0,Forage,\r\n"); var before = File.ReadAllBytes(f.Ui); Refused(() => NativeSetup.Apply(f.Package, true, () => false)); Check(before.SequenceEqual(File.ReadAllBytes(f.Ui))); });
        test("Tampered native package fails its integrity check", () => { var f = Fixture(); NativeSetup.Generate(f.Root, "ExampleHero", "example", f.Package); File.AppendAllText(Path.Combine(f.Package, "compact", "ExampleHero_example_LO1.ini"), "tampered"); Refused(() => NativeSetup.Apply(f.Package, true, () => false)); });
        test("Native package rejects invalid profile and escaped file paths", () => { var f = Fixture(); Refused(() => NativeSetup.Generate(f.Root, "../Other", "example", f.Package)); var plan = NativeSetup.Generate(f.Root, "ExampleHero", "example", f.Package); plan.Files[0].RelativePath = "../outside.ini"; Json.Write(Path.Combine(f.Package, "manifest.json"), plan); Refused(() => NativeSetup.Apply(f.Package, true, () => false)); });
        test("Repeated native package generation does not create duplicate controls", () => { var f = Fixture(); NativeSetup.Generate(f.Root, "ExampleHero", "example", f.Package); NativeSetup.Apply(f.Package, true, () => false); Refused(() => NativeSetup.Generate(f.Root, "ExampleHero", "example", f.Package + "-duplicate")); Check(!Directory.Exists(f.Package + "-duplicate")); });
        test("Native setup preserves Unicode INI encoding", () => { foreach (var encoding in new Encoding[] { Encoding.Unicode, Encoding.BigEndianUnicode, Encoding.UTF32 }) { var f = Fixture(); string text = File.ReadAllText(f.Character) + "[Notes]\r\nName=Glacé\r\n"; File.WriteAllText(f.Character, text, encoding); NativeSetup.Generate(f.Root, "ExampleHero", "example", f.Package); NativeSetup.Apply(f.Package, false, () => false); Check(File.ReadAllBytes(f.Character).AsSpan().StartsWith(encoding.GetPreamble())); Check(File.ReadAllText(f.Character).Contains("Name=Glacé")); } });
    }
}
